import { test, expect } from '@playwright/test';

test.describe('File Download Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully download a previously uploaded file', async ({ page }) => {
    // Upload a file using getByLabel
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await uploadButton.click();

    const fileInput = page.getByLabel(/choose file/i);
    await fileInput.setInputFiles('fixtures/sample-document.pdf');

    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await uploadButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Navigate to download page
    const downloadButton = page.getByRole('button', { name: /download file/i });
    await downloadButton.click();

    // Verify download dialog appears
    const downloadDialog = page.getByRole('dialog', { name: /download file/i });
    await expect(downloadDialog).toBeVisible();

    // Verify file name is displayed
    const fileName = page.getByText(/sample-document.pdf/i);
    await expect(fileName).toBeVisible();

    // Verify download button is enabled
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeEnabled();

    // Click download button
    await downloadButton.click();

    // Verify file is downloaded
    const downloadSuccess = page.getByText(/file downloaded/i);
    await expect(downloadSuccess).toBeVisible();

    // Verify file exists in downloads directory
    const downloadsDir = page.locator('[data-testid="downloads-directory"]');
    await expect(downloadsDir).toBeVisible();

    const filePath = page.locator('[data-testid="downloaded-file-path"]');
    await expect(filePath).toContainText('sample-document.pdf');

    // Verify file is accessible
    const fileContent = page.locator('[data-testid="downloaded-file-content"]');
    await expect(fileContent).toBeVisible();
  });

  test('should handle failed download due to network error', async ({ page }) => {
    // Upload a file using getByLabel
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await uploadButton.click();

    const fileInput = page.getByLabel(/choose file/i);
    await fileInput.setInputFiles('fixtures/sample-document.pdf');

    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await uploadButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Navigate to download page
    const downloadButton = page.getByRole('button', { name: /download file/i });
    await downloadButton.click();

    // Verify download dialog appears
    const downloadDialog = page.getByRole('dialog', { name: /download file/i });
    await expect(downloadDialog).toBeVisible();

    // Mock network error
    await page.route('**/api/download/sample-document.pdf', (route) => {
      route.abort('Failed to download file');
    });

    // Verify error message appears
    const errorMessage = page.getByText(/download failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry download/i });
    await expect(retryButton).toBeVisible();

    // Click retry button
    await retryButton.click();

    // Verify download dialog reappears
    await expect(downloadDialog).toBeVisible();

    // Verify file name is still displayed
    const fileName = page.getByText(/sample-document.pdf/i);
    await expect(fileName).toBeVisible();

    // Verify download button is now enabled
    const downloadButton = page.getByRole('button', { name: /download/i });
    await expect(downloadButton).toBeEnabled();

    // Click download button
    await downloadButton.click();

    // Verify file is downloaded
    const downloadSuccess = page.getByText(/file downloaded/i);
    await expect(downloadSuccess).toBeVisible();

    // Verify file exists in downloads directory
    const downloadsDir = page.locator('[data-testid="downloads-directory"]');
    await expect(downloadsDir).toBeVisible();

    const filePath = page.locator('[data-testid="downloaded-file-path"]');
    await expect(filePath).toContainText('sample-document.pdf');

    // Verify file is accessible
    const fileContent = page.locator('[data-testid="downloaded-file-content"]');
    await expect(fileContent).toBeVisible();
  });
});
